            "segment": {
              "endIndex": 91,
              "text": "Otters are semi-aquatic carnivorous mammals belonging to the weasel family (**mustelids**)."
            },
            "groundingChunkIndices": [
              0,
              1
            ]
          },
          {
            "segment": {
              "startIndex": 221,
              "endIndex": 322,
              "text": "*   **Physical Features:** They have long, slim bodies, webbed feet for swimming, and powerful tails."
            },
            "groundingChunkIndices": [
              2
            ]
          },
          {
            "segment": {
              "startIndex": 323,
              "endIndex": 464,
              "text": "Sea otters have the **thickest fur** of any animal—up to one million hairs per square inch—which keeps them warm since they lack blubber."
            },
            "groundingChunkIndices": [
              3
            ]
          },
          {
            "segment": {
              "startIndex": 465,
              "endIndex": 555,
              "text": "*   **Diet:** They are skilled hunters that primarily eat fish, crabs, mussels, and frogs."
